CREATE TABLE IF NOT EXISTS catalog_products(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),latest_revision TEXT,published_revision TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS catalog_product_revisions(id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES catalog_products(id),owner_id TEXT NOT NULL REFERENCES catalog_accounts(id),name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>=0),stock INTEGER NOT NULL CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1,media_id TEXT NOT NULL REFERENCES catalog_media(id),status TEXT NOT NULL CHECK(status IN('pending','approved','rejected')),reason TEXT NOT NULL DEFAULT '',reviewer TEXT REFERENCES catalog_accounts(id),reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS catalog_product_review_queue ON catalog_product_revisions(status,created_at);
